#!/usr/bin/env python3
"""Demo service: loops forever printing a heartbeat once per second."""
import time

if __name__ == "__main__":
    n = 0
    print("worker: starting heartbeat loop", flush=True)
    while True:
        n += 1
        print(f"worker: heartbeat {n}", flush=True)
        time.sleep(1.0)

