def shutdown_children(self) -> None:
    """SIGTERM every child, wait, escalate to SIGKILL."""
    # Snapshot Popen handles under lock: monitor threads may set
    # st.proc = None at any moment when a child exits.
    live = []
    for st in self.states:
        with st.lock:
            proc = st.proc
        if proc is not None and proc.poll() is None:
            live.append((st, proc))
    for st, proc in live:
        self.log(st, f"sending SIGTERM to pid={proc.pid}")
        try:
            proc.terminate()
        except ProcessLookupError:
